/**
 * Help section for explaining how to use a keyboard to interact with the grab/release interaction.
 *
 * @author Michael Kauzmann (PhET Interactive Simulations)
 */
import { string_scenery_phet_keyboardHelpDialog_grabOrReleaseHeadingPattern_StringProperty } from '../../strings/keyboardHelpDialog/grabOrReleaseHeadingPattern.js';
import { string_scenery_phet_keyboardHelpDialog_grabOrReleaseLabelPattern_StringProperty } from '../../strings/keyboardHelpDialog/grabOrReleaseLabelPattern.js';
import { string_scenery_phet_a11y_keyboardHelpDialog_grabOrReleaseDescriptionPattern_StringProperty } from '../../strings/a11y/keyboardHelpDialog/grabOrReleaseDescriptionPattern.js';
import '../../../../globals.js';
import PatternStringProperty from '../../../../axon/js/PatternStringProperty.js';
import { combineOptions } from '../../../../phet-core/js/optionize.js';
import Tandem from '../../../../tandem/js/Tandem.js';
import sceneryPhet from '../../sceneryPhet.js';
import TextKeyNode from '../TextKeyNode.js';
import KeyboardHelpIconFactory from './KeyboardHelpIconFactory.js';
import KeyboardHelpSection from './KeyboardHelpSection.js';
import KeyboardHelpSectionRow from './KeyboardHelpSectionRow.js';
export default class GrabReleaseKeyboardHelpSection extends KeyboardHelpSection {
    /**
     * @param thingAsTitle - the item being grabbed, capitalized as a title
     * @param thingAsLowerCase - the item being grabbed, lower case as used in a sentence.
     * @param [providedOptions]
     */
    constructor(thingAsTitle, thingAsLowerCase, providedOptions) {
        const options = combineOptions({
            // There is only a single paragraph for this section, no list needed in the PDOM
            a11yContentTagName: null
        }, providedOptions);
        // the visible heading string
        const headingStringProperty = new PatternStringProperty(string_scenery_phet_keyboardHelpDialog_grabOrReleaseHeadingPattern_StringProperty, {
            thing: thingAsTitle
        }, { tandem: Tandem.OPT_OUT });
        // the visible label string
        const labelStringProperty = new PatternStringProperty(string_scenery_phet_keyboardHelpDialog_grabOrReleaseLabelPattern_StringProperty, {
            thing: thingAsLowerCase
        }, { tandem: Tandem.OPT_OUT });
        // the string for the PDOM
        const descriptionStringProperty = new PatternStringProperty(string_scenery_phet_a11y_keyboardHelpDialog_grabOrReleaseDescriptionPattern_StringProperty, {
            thing: thingAsLowerCase
        }, { tandem: Tandem.OPT_OUT });
        const spaceKeyNode = TextKeyNode.space();
        const enterKeyNode = TextKeyNode.enter();
        const icons = KeyboardHelpIconFactory.iconOrIcon(spaceKeyNode, enterKeyNode);
        const labelWithContentRow = KeyboardHelpSectionRow.labelWithIcon(labelStringProperty, icons, {
            labelInnerContent: descriptionStringProperty,
            iconOptions: {
                tagName: 'p' // it is the only item, so it is 'p' rather than 'li'
            }
        });
        super(headingStringProperty, [labelWithContentRow], options);
    }
}
sceneryPhet.register('GrabReleaseKeyboardHelpSection', GrabReleaseKeyboardHelpSection);
